def chamar(metodo, caminho, escopo, **kw):
    """Repete uma unica vez quando o token expira; 401 na segunda = problema de certificado."""
    for tentativa in (1, 2):
        r = requests.request(metodo, f"{BASE}{caminho}", cert=CERT,
                             headers={"Authorization": f"Bearer {token(escopo)}"},
                             timeout=60, **kw)
        if r.status_code == 401 and tentativa == 1:
            _cache.pop(escopo, None)      # descarta o token e tenta de novo
            continue
        return r

# 1) autorizacao (recorrencia)
rec = requests.post(f"{BASE}/rec", json={
    "vinculo": {"contrato": "CT-2026-4210", "objeto": "Plano mensal",
                "devedor": {"cpf": "00000000000", "nome": "Fulano de Tal"}},
